callGraph.callee:
jobRepository
                .findByStatus(JobStatus.APPROVED)
                .stream()
                .map(job -> {

                    JobResponse response =
                            JobResponse.from(job);

                    EligibilityService.EligibilityResult result =
                            eligibilityService.check(
                                    job,
                                    profile
                            );

                    response.setEligible(
                            result.eligible()
                    );

                    response.setEligibilityReason(
                            result.reason()
                    );

                    return response;
                }).toList
